#!/bin/bash
#SBATCH --job-name=cob-phi-sealed
#SBATCH --account=xxx
#SBATCH --partition=gpu
#SBATCH --time=36:00:00
#SBATCH --nodes=1
#SBATCH --gpus-per-node=1
#SBATCH --cpus-per-task=7
#SBATCH --ntasks-per-node=1
#SBATCH --signal=B:USR1@120
#SBATCH --output=%x-%j.out
#SBATCH --error=%x-%j.err

# generated by src/experiments/v5/slurm.py for backend cuda, profile roihu
# stub profile, written and exercised by the tests but never run: it exists to prove a cuda + roihu launch goes through the same shared path with no training-code change. its partitions and setup lines are placeholders and must be filled from Roihu's own documentation before use
# backend: every completed run in this project; bitsandbytes 8-bit adamw is available and unsloth selects sdpa or xformers by capability
# layout run, run phi-sealed-v5-r01
# all three validation evaluations of this attempt must pass --run phi-sealed-v5-r01:
# selection groups results by an exact match on that string and normalizes nothing

set -euo pipefail

if [ -z "${COB_PROFILE_ROOT:-}" ]; then
  echo "COB_PROFILE_ROOT is not set: it must point at this profile's root (caches, checkpoints, logs)" >&2
  exit 2
fi
mkdir -p "${COB_PROFILE_ROOT}/logs" "${COB_PROFILE_ROOT}/models/training/sealed/phi/phi-sealed-v5-r01" "${COB_PROFILE_ROOT}/models/training/sealed/phi/phi-sealed-v5-r01/checkpoints"

# site setup
# module load <site python/cuda modules>

# every path comes from the execution profile, none is hardcoded in the python
export HF_HOME="${COB_PROFILE_ROOT}/hf-cache"
export HF_HUB_CACHE="${COB_PROFILE_ROOT}/hf-cache/hub"
export PYTHONPATH="${PYTHONPATH:-}:$(pwd)"
export COB_DATASET_VERSION=v5

if [ -f "${COB_PROFILE_ROOT}/models/training/sealed/phi/phi-sealed-v5-r01/TRAINING_DONE" ]; then
  echo "training already finished, nothing to do"
  exit 0
fi

# the run itself: one continuous 3-epoch run, an adapter saved at every epoch boundary,
# resuming from the newest complete checkpoint if this is a continuation.
#
# recorded caveat, carried here and on every result record (results_store.py
# EPOCH_COMPARABILITY_NOTE): the linear LR schedule decays across the whole 3-epoch
# horizon, so this run's epoch-1 and epoch-2 adapters are NOT directly comparable to v4's
# separately trained epoch-1 and epoch-2 families. compare v5 epochs with each other, and
# v4 against v5 only at the final selected checkpoint.
# errexit is lifted around it on purpose: a non-zero exit is the wall-time case this
# script exists to handle, and under set -e the shell would die before reading it
# one resubmission per job, whoever asks for it. the wall-time trap and the non-zero
# exit path below can both reach this; the guard is what stops them queueing two
# successors for the same job
COB_RESUBMITTED=0
cob_resubmit() {
  if [ "$COB_RESUBMITTED" -ne 0 ]; then return 0; fi
  COB_RESUBMITTED=1
  attempt="${COB_CONTINUATION:-0}"
  if [ "$attempt" -ge "12" ]; then
    echo "reached 12 continuations without finishing, stopping" >&2
    return 1
  fi
  export COB_CONTINUATION=$((attempt + 1))
  echo "resubmitting continuation $COB_CONTINUATION"
  sbatch --dependency=afterany:${SLURM_JOB_ID} --export=ALL "$0"
}

# Slurm signals the batch shell shortly before the wall clock. resubmit from here, then
# stop the trainer and leave cleanly: the successor picks up from the newest checkpoint
cob_on_walltime() {
  echo "wall time approaching, resubmitting before the kill"
  cob_resubmit || true
  kill "${train_pid:-0}" 2>/dev/null || true
  exit 0
}
trap cob_on_walltime USR1

COB_INNER="${COB_JOB_CACHE:-${TMPDIR:-/tmp}}/cob-inner-${SLURM_JOB_ID:-$$}.sh"
# the training command, staged to a file so it can run in the background
cat > "$COB_INNER" <<'COB_CONTAINER'
python src/experiments/finetune_lora.py --dataset v5_sealed --max-seq-length 1024 --batch-size 8 --grad-accum 2 --base-model "${COB_PROFILE_ROOT}/models/base-checkpoints/hf/phi4mini-v2-base" --instruction-part '<|user|>' --response-part '<|assistant|>' --lora-targets qkv_proj,o_proj,gate_up_proj,down_proj --save-steps 250 --num-train-epochs 3 --save-epoch-adapters --resume --optim adamw_8bit --output-dir "${COB_PROFILE_ROOT}/models/training/sealed/phi/phi-sealed-v5-r01" --checkpoint-dir "${COB_PROFILE_ROOT}/models/training/sealed/phi/phi-sealed-v5-r01/checkpoints"
COB_CONTAINER

# backgrounded on purpose: `wait` is interruptible, a synchronous call is not, and this
# shell has to stay free to run the trap above while training is still going
set +e
bash -s < "$COB_INNER" &
train_pid=$!
wait "$train_pid"; status=$?
# wait returns >128 when a handled signal interrupts it, so go back to waiting
while [ "$status" -gt 128 ] && kill -0 "$train_pid" 2>/dev/null; do
  wait "$train_pid"; status=$?
done
set -e

if [ $status -eq 0 ]; then
  touch "${COB_PROFILE_ROOT}/models/training/sealed/phi/phi-sealed-v5-r01/TRAINING_DONE"
  echo "training finished"
  exit 0
fi

# died for some other reason: continue from the last checkpoint
cob_resubmit || exit 1

